root = Path("/tmp/aimo-e37")
entries = json.loads('{"train/eval_e36_budget_path.py": "\\"\\"\\"Evaluate the pre-registered E36 budget-path reasoning diagnostic.\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport json\\nimport math\\nimport re\\nfrom collections import Counter\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom sklearn.impute import SimpleImputer\\nfrom sklearn.linear_model import LogisticRegression\\nfrom sklearn.metrics import balanced_accuracy_score, roc_auc_score\\nfrom sklearn.model_selection import GroupKFold\\nfrom sklearn.pipeline import make_pipeline\\nfrom sklearn.preprocessing import StandardScaler\\n\\n\\nBUDGETS = (2_048, 4_096, 8_192, 16_384)\\nLABEL_BUDGET = 16_384\\nSEED = 36\\nMARKERS = (\\"wait\\", \\"however\\", \\"alternatively\\", \\"instead\\", \\"check\\", \\"verify\\", \\"reconsider\\", \\"mistake\\")\\n\\n\\ndef read_shards(directory: Path) -> pd.DataFrame:\\n    paths = sorted(directory.glob(\\"*.parquet\\"))\\n    if not paths:\\n        raise SystemExit(f\\"no parquet shards in {directory}\\")\\n    return pd.concat((pd.read_parquet(path) for path in paths), ignore_index=True)\\n\\n\\ndef canonical_problem_id(value: object, variant: object, source: str) -> str:\\n    value, variant = str(value), str(variant)\\n    if source == \\"math_perturb\\":\\n        suffix = f\\"#{variant}\\"\\n        if not value.endswith(suffix):\\n            raise ValueError(f\\"unexpected MATH-Perturb problem_id: {value!r}\\")\\n        return value[: -len(suffix)]\\n    if source == \\"putnam_axiom\\":\\n        pattern = r\\"^putnam_orig_(.+::.+)$\\" if variant == \\"original\\" else r\\"^putnam_var_(.+::.+)_\\\\d+$\\"\\n        match = re.fullmatch(pattern, value)\\n        if match is None:\\n            raise ValueError(f\\"unexpected Putnam problem_id: {value!r}\\")\\n        return \\"putnam_\\" + match.group(1)\\n    raise ValueError(source)\\n\\n\\ndef normalize_answer(value: object) -> str:\\n    text = \\"\\" if value is None else str(value).lower()\\n    return re.sub(r\\"[\\\\s$\\\\[\\\\]{},]\\", \\"\\", text)\\n\\n\\ndef repeated_line_fraction(trace: str) -> float:\\n    lines = [re.sub(r\\"\\\\s+\\", \\" \\", line.strip().lower()) for line in str(trace).splitlines()]\\n    lines = [line for line in lines if line]\\n    if not lines:\\n        return 0.0\\n    return 1.0 - len(set(lines)) / len(lines)\\n\\n\\ndef trace_features(part: pd.DataFrame) -> dict[str, float]:\\n    rows = {}\\n    for budget in BUDGETS:\\n        selected = part.loc[part[\\"token_budget\\"] == budget]\\n        if len(selected) != 1:\\n            raise ValueError(f\\"expected one original row at budget {budget}, found {len(selected)}\\")\\n        rows[budget] = selected.iloc[0]\\n\\n    answers = [normalize_answer(rows[b][\\"predicted_answer\\"]) for b in BUDGETS]\\n    nonempty = [answer for answer in answers if answer]\\n    counts = Counter(nonempty)\\n    modal_fraction = max(counts.values()) / len(nonempty) if nonempty else 0.0\\n    unique_fraction = len(counts) / len(nonempty) if nonempty else 1.0\\n    adjacent = [answers[i] == answers[i + 1] and bool(answers[i]) for i in range(len(answers) - 1)]\\n    final_matches = [answer == answers[-1] and bool(answer) for answer in answers[:-1]]\\n    natural = [not bool(rows[b][\\"answer_forced\\"]) for b in BUDGETS]\\n    first_natural = next((math.log2(budget) for budget, flag in zip(BUDGETS, natural) if flag), 15.0)\\n    words = [len(str(rows[b][\\"trace\\"]).split()) for b in BUDGETS]\\n    final_trace = str(rows[BUDGETS[-1]][\\"trace\\"]).lower()\\n    marker_count = sum(len(re.findall(rf\\"\\\\b{re.escape(marker)}\\\\b\\", final_trace)) for marker in MARKERS)\\n    final_words = max(words[-1], 1)\\n\\n    result: dict[str, float] = {}\\n    for budget, flag, word_count in zip(BUDGETS, natural, words):\\n        result[f\\"natural_{budget}\\"] = float(flag)\\n        result[f\\"log_words_{budget}\\"] = math.log1p(word_count)\\n    result.update(\\n        natural_fraction=float(np.mean(natural)),\\n        first_natural_log2=float(first_natural),\\n        answer_nonempty_fraction=float(np.mean([bool(answer) for answer in answers])),\\n        answer_modal_fraction=float(modal_fraction),\\n        answer_unique_fraction=float(unique_fraction),\\n        answer_adjacent_agreement=float(np.mean(adjacent)),\\n        answer_final_agreement=float(np.mean(final_matches)),\\n        trace_growth_8k_16k=float((words[-1] + 1) / (words[-2] + 1)),\\n        correction_markers_per_1k=float(1_000 * marker_count / final_words),\\n        repeated_line_fraction_16k=float(repeated_line_fraction(final_trace)),\\n    )\\n    return result\\n\\n\\ndef build_examples(frame: pd.DataFrame, source: str) -> pd.DataFrame:\\n    required = {\\n        \\"model\\", \\"token_budget\\", \\"problem_id\\", \\"variant\\", \\"predicted_answer\\",\\n        \\"correct_strict\\", \\"answer_forced\\", \\"trace\\",\\n    }\\n    missing = required - set(frame.columns)\\n    if missing:\\n        raise ValueError(f\\"missing columns: {sorted(missing)}\\")\\n    frame = frame.loc[frame[\\"token_budget\\"].isin(BUDGETS)].copy()\\n    frame[\\"canonical_id\\"] = [\\n        canonical_problem_id(value, variant, source)\\n        for value, variant in zip(frame[\\"problem_id\\"], frame[\\"variant\\"])\\n    ]\\n    original_name = \\"base\\" if source == \\"math_perturb\\" else \\"original\\"\\n    rows = []\\n    for (problem_id, model), part in frame.groupby([\\"canonical_id\\", \\"model\\"], sort=True):\\n        at_label = part.loc[part[\\"token_budget\\"] == LABEL_BUDGET]\\n        original_label = at_label.loc[at_label[\\"variant\\"] == original_name, \\"correct_strict\\"]\\n        if len(original_label) != 1:\\n            raise ValueError(f\\"{problem_id}/{model}: expected one label-budget original\\")\\n        if not bool(original_label.iloc[0]):\\n            continue\\n        if source == \\"math_perturb\\":\\n            variants = at_label.set_index(\\"variant\\")[\\"correct_strict\\"]\\n            if not {\\"simple\\", \\"hard\\"}.issubset(variants.index):\\n                raise ValueError(f\\"{problem_id}/{model}: missing MATH variants\\")\\n            robust = bool(variants[\\"simple\\"] and variants[\\"hard\\"])\\n        else:\\n            variants = at_label.loc[at_label[\\"variant\\"] == \\"variation\\", \\"correct_strict\\"]\\n            if variants.empty:\\n                raise ValueError(f\\"{problem_id}/{model}: missing Putnam variations\\")\\n            robust = bool(variants.astype(bool).all())\\n        original = part.loc[part[\\"variant\\"] == original_name]\\n        rows.append({\\n            \\"problem_id\\": problem_id,\\n            \\"model\\": str(model),\\n            \\"is_robust\\": robust,\\n            **trace_features(original),\\n        })\\n    return pd.DataFrame(rows)\\n\\n\\ndef feature_columns(frame: pd.DataFrame) -> list[str]:\\n    return [column for column in frame.columns if column not in {\\"problem_id\\", \\"model\\", \\"is_robust\\"}]\\n\\n\\ndef make_model() -> object:\\n    return make_pipeline(\\n        SimpleImputer(strategy=\\"median\\"),\\n        StandardScaler(),\\n        LogisticRegression(C=1.0, class_weight=\\"balanced\\", max_iter=2_000, random_state=SEED),\\n    )\\n\\n\\ndef choose_threshold(y: np.ndarray, scores: np.ndarray) -> float:\\n    candidates = np.unique(scores)\\n    values = np.array([balanced_accuracy_score(y, scores >= threshold) for threshold in candidates])\\n    return float(candidates[np.flatnonzero(values == values.max())[-1]])\\n\\n\\ndef fit_predict(train: pd.DataFrame, holdout: pd.DataFrame) -> tuple[np.ndarray, float]:\\n    columns = feature_columns(train)\\n    if columns != feature_columns(holdout):\\n        raise ValueError(\\"feature columns differ between sources\\")\\n    x, y = train[columns], train[\\"is_robust\\"].to_numpy(bool)\\n    groups = train[\\"problem_id\\"].to_numpy(str)\\n    oof = np.full(len(train), np.nan)\\n    for fit_index, score_index in GroupKFold(5).split(x, y, groups):\\n        model = make_model()\\n        model.fit(x.iloc[fit_index], y[fit_index])\\n        oof[score_index] = model.predict_proba(x.iloc[score_index])[:, 1]\\n    threshold = choose_threshold(y, oof)\\n    model = make_model()\\n    model.fit(x, y)\\n    return model.predict_proba(holdout[columns])[:, 1], threshold\\n\\n\\ndef grouped_auc_ci(frame: pd.DataFrame, scores: np.ndarray, replicates: int) -> tuple[float, float]:\\n    ids = frame[\\"problem_id\\"].drop_duplicates().to_numpy(str)\\n    indices = {problem_id: np.flatnonzero(frame[\\"problem_id\\"].to_numpy(str) == problem_id) for problem_id in ids}\\n    rng = np.random.default_rng(SEED)\\n    values = []\\n    y = frame[\\"is_robust\\"].to_numpy(bool)\\n    for _ in range(replicates):\\n        sampled = rng.choice(ids, len(ids), replace=True)\\n        selected = np.concatenate([indices[problem_id] for problem_id in sampled])\\n        if np.unique(y[selected]).size == 2:\\n            values.append(roc_auc_score(y[selected], scores[selected]))\\n    return tuple(float(value) for value in np.quantile(values, [0.025, 0.975]))\\n\\n\\ndef evaluate(math_frame: pd.DataFrame, putnam_frame: pd.DataFrame, bootstrap: int = 5_000) -> dict:\\n    train = build_examples(math_frame, \\"math_perturb\\")\\n    holdout = build_examples(putnam_frame, \\"putnam_axiom\\")\\n    scores, threshold = fit_predict(train, holdout)\\n    y = holdout[\\"is_robust\\"].to_numpy(bool)\\n    auc = float(roc_auc_score(y, scores))\\n    ci = grouped_auc_ci(holdout, scores, bootstrap)\\n    balanced = float(balanced_accuracy_score(y, scores >= threshold))\\n    by_model = {}\\n    for model, part in holdout.groupby(\\"model\\", sort=True):\\n        index = part.index.to_numpy()\\n        local_y = part[\\"is_robust\\"].to_numpy(bool)\\n        by_model[str(model)] = None if np.unique(local_y).size < 2 else float(roc_auc_score(local_y, scores[index]))\\n    counts = lambda frame: {\\n        \\"n\\": int(len(frame)),\\n        \\"problems\\": int(frame[\\"problem_id\\"].nunique()),\\n        \\"robust\\": int(frame[\\"is_robust\\"].sum()),\\n        \\"spurious\\": int((~frame[\\"is_robust\\"]).sum()),\\n    }\\n    train_counts, holdout_counts = counts(train), counts(holdout)\\n    valid_model_aucs = [value for value in by_model.values() if value is not None]\\n    gates = {\\n        \\"train_at_least_100_each\\": min(train_counts[\\"robust\\"], train_counts[\\"spurious\\"]) >= 100,\\n        \\"holdout_at_least_40_each\\": min(holdout_counts[\\"robust\\"], holdout_counts[\\"spurious\\"]) >= 40,\\n        \\"auc_at_least_0_65\\": auc >= 0.65,\\n        \\"auc_ci_lower_above_0_50\\": ci[0] > 0.50,\\n        \\"balanced_accuracy_at_least_0_60\\": balanced >= 0.60,\\n        \\"all_model_aucs_at_least_0_50\\": bool(valid_model_aucs) and min(valid_model_aucs) >= 0.50,\\n        \\"three_model_aucs_at_least_0_58\\": sum(value >= 0.58 for value in valid_model_aucs) >= 3,\\n    }\\n    diagnostics = {}\\n    for column in feature_columns(train):\\n        values = holdout[column].to_numpy(float)\\n        diagnostics[column] = None if np.unique(values).size < 2 else float(roc_auc_score(y, values))\\n    return {\\n        \\"train\\": train_counts,\\n        \\"holdout\\": holdout_counts,\\n        \\"feature_count\\": len(feature_columns(train)),\\n        \\"oof_threshold\\": threshold,\\n        \\"holdout_auc\\": auc,\\n        \\"holdout_auc_ci95_problem_bootstrap\\": list(ci),\\n        \\"holdout_balanced_accuracy\\": balanced,\\n        \\"model_aucs\\": by_model,\\n        \\"diagnostic_feature_aucs_unoriented\\": diagnostics,\\n        \\"gates\\": gates,\\n        \\"passed\\": bool(all(gates.values())),\\n    }\\n\\n\\ndef main() -> None:\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--math-dir\\", type=Path, required=True)\\n    parser.add_argument(\\"--putnam-dir\\", type=Path, required=True)\\n    parser.add_argument(\\"--bootstrap\\", type=int, default=5_000)\\n    parser.add_argument(\\"--out\\", type=Path)\\n    args = parser.parse_args()\\n    result = evaluate(read_shards(args.math_dir), read_shards(args.putnam_dir), args.bootstrap)\\n    payload = json.dumps(result, indent=2)\\n    print(payload)\\n    if args.out:\\n        args.out.parent.mkdir(parents=True, exist_ok=True)\\n        args.out.write_text(payload + \\"\\\\n\\", encoding=\\"utf-8\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "train/eval_e37_gsm_confirmation.py": "\\"\\"\\"Evaluate E37 on untouched GSM-Plus outcomes with E36\'s frozen score.\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport json\\nfrom pathlib import Path\\n\\nimport numpy as np\\nimport pandas as pd\\nfrom sklearn.metrics import balanced_accuracy_score, roc_auc_score\\n\\nfrom eval_e36_budget_path import (\\n    BUDGETS,\\n    LABEL_BUDGET,\\n    build_examples,\\n    feature_columns,\\n    grouped_auc_ci,\\n    make_model,\\n    read_shards,\\n    trace_features,\\n)\\n\\n\\nANCHOR = \\"problem understanding\\"\\nEXCLUDED = \\"critical thinking\\"\\n\\n\\ndef build_gsm_examples(frame: pd.DataFrame) -> pd.DataFrame:\\n    required = {\\n        \\"model\\", \\"token_budget\\", \\"problem_id\\", \\"variant\\", \\"predicted_answer\\",\\n        \\"correct_strict\\", \\"answer_forced\\", \\"trace\\",\\n    }\\n    missing = required - set(frame.columns)\\n    if missing:\\n        raise ValueError(f\\"missing columns: {sorted(missing)}\\")\\n    frame = frame.loc[frame[\\"token_budget\\"].isin(BUDGETS)].copy()\\n    try:\\n        numeric_id = frame[\\"problem_id\\"].astype(int)\\n    except (TypeError, ValueError) as exc:\\n        raise ValueError(\\"GSM-Plus problem IDs must be integers\\") from exc\\n    frame[\\"canonical_id\\"] = (numeric_id // 8).astype(str)\\n    rows = []\\n    for (problem_id, model), part in frame.groupby([\\"canonical_id\\", \\"model\\"], sort=True):\\n        at_label = part.loc[part[\\"token_budget\\"] == LABEL_BUDGET]\\n        variants = at_label.loc[at_label[\\"variant\\"] != EXCLUDED]\\n        if len(variants) != 7 or variants[\\"variant\\"].nunique() != 7:\\n            raise ValueError(f\\"{problem_id}/{model}: expected seven distinct scorable variants\\")\\n        anchor_label = variants.loc[variants[\\"variant\\"] == ANCHOR, \\"correct_strict\\"]\\n        if len(anchor_label) != 1:\\n            raise ValueError(f\\"{problem_id}/{model}: expected one anchor\\")\\n        if not bool(anchor_label.iloc[0]):\\n            continue\\n        correct = int(variants[\\"correct_strict\\"].astype(bool).sum())\\n        if correct == 6:\\n            continue\\n        robust = correct == 7\\n        anchor = part.loc[part[\\"variant\\"] == ANCHOR]\\n        rows.append({\\n            \\"problem_id\\": problem_id,\\n            \\"model\\": str(model),\\n            \\"is_robust\\": robust,\\n            **trace_features(anchor),\\n        })\\n    return pd.DataFrame(rows)\\n\\n\\ndef half_rank_by_model(frame: pd.DataFrame, scores: np.ndarray) -> np.ndarray:\\n    predictions = np.zeros(len(frame), dtype=bool)\\n    for _, part in frame.groupby(\\"model\\", sort=True):\\n        index = part.index.to_numpy()\\n        order = np.lexsort((part[\\"problem_id\\"].to_numpy(str), scores[index]))\\n        predictions[index[order[len(order) // 2 :]]] = True\\n    return predictions\\n\\n\\ndef evaluate(math_frame: pd.DataFrame, gsm_frame: pd.DataFrame, bootstrap: int = 5_000) -> dict:\\n    train = build_examples(math_frame, \\"math_perturb\\")\\n    holdout = build_gsm_examples(gsm_frame)\\n    columns = feature_columns(train)\\n    if columns != feature_columns(holdout):\\n        raise ValueError(\\"feature columns differ between MATH-Perturb and GSM-Plus\\")\\n    model = make_model()\\n    model.fit(train[columns], train[\\"is_robust\\"].to_numpy(bool))\\n    scores = model.predict_proba(holdout[columns])[:, 1]\\n    y = holdout[\\"is_robust\\"].to_numpy(bool)\\n    predictions = half_rank_by_model(holdout, scores)\\n    auc = float(roc_auc_score(y, scores))\\n    ci = grouped_auc_ci(holdout, scores, bootstrap)\\n    balanced = float(balanced_accuracy_score(y, predictions))\\n    by_model = {}\\n    for model_name, part in holdout.groupby(\\"model\\", sort=True):\\n        index = part.index.to_numpy()\\n        local_y = part[\\"is_robust\\"].to_numpy(bool)\\n        by_model[str(model_name)] = None if np.unique(local_y).size < 2 else float(\\n            roc_auc_score(local_y, scores[index])\\n        )\\n    counts = {\\n        \\"n\\": int(len(holdout)),\\n        \\"problems\\": int(holdout[\\"problem_id\\"].nunique()),\\n        \\"robust\\": int(y.sum()),\\n        \\"spurious\\": int((~y).sum()),\\n    }\\n    valid_model_aucs = [value for value in by_model.values() if value is not None]\\n    gates = {\\n        \\"at_least_50_each\\": min(counts[\\"robust\\"], counts[\\"spurious\\"]) >= 50,\\n        \\"auc_at_least_0_65\\": auc >= 0.65,\\n        \\"auc_ci_lower_above_0_50\\": ci[0] > 0.50,\\n        \\"balanced_accuracy_at_least_0_60\\": balanced >= 0.60,\\n        \\"all_model_aucs_at_least_0_50\\": bool(valid_model_aucs) and min(valid_model_aucs) >= 0.50,\\n        \\"three_model_aucs_at_least_0_58\\": sum(value >= 0.58 for value in valid_model_aucs) >= 3,\\n    }\\n    return {\\n        \\"holdout\\": counts,\\n        \\"holdout_auc\\": auc,\\n        \\"holdout_auc_ci95_problem_bootstrap\\": list(ci),\\n        \\"holdout_half_rank_balanced_accuracy\\": balanced,\\n        \\"model_aucs\\": by_model,\\n        \\"gates\\": gates,\\n        \\"passed\\": bool(all(gates.values())),\\n    }\\n\\n\\ndef main() -> None:\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--math-dir\\", type=Path, required=True)\\n    parser.add_argument(\\"--gsm-dir\\", type=Path, required=True)\\n    parser.add_argument(\\"--bootstrap\\", type=int, default=5_000)\\n    parser.add_argument(\\"--out\\", type=Path)\\n    args = parser.parse_args()\\n    result = evaluate(read_shards(args.math_dir), read_shards(args.gsm_dir), args.bootstrap)\\n    payload = json.dumps(result, indent=2)\\n    print(payload)\\n    if args.out:\\n        args.out.parent.mkdir(parents=True, exist_ok=True)\\n        args.out.write_text(payload + \\"\\\\n\\", encoding=\\"utf-8\\")\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "train/run_e37_confirmation.py": "\\"\\"\\"Run the frozen E37 confirmation from its pinned public archive, recording provenance.\\n\\nDownload only MATH-Perturb and GSM-Plus. Keep original traces at the four frozen budgets\\nand variant correctness at the label budget; variant traces never enter the predictor.\\nThe evaluator and gates remain exactly those in E37_PROTOCOL.md.\\n\\nRun: python train/run_e37_confirmation.py --out-dir runs/e37-confirmation\\n\\"\\"\\"\\n\\nfrom __future__ import annotations\\n\\nimport argparse\\nimport hashlib\\nimport importlib.metadata\\nimport json\\nimport platform\\nimport time\\nfrom pathlib import Path\\n\\nimport pandas as pd\\nfrom huggingface_hub import HfApi, hf_hub_download\\n\\nfrom eval_e36_budget_path import BUDGETS, LABEL_BUDGET\\nfrom eval_e37_gsm_confirmation import ANCHOR, evaluate\\n\\nDATASET = \\"ssubhnil/Qwen3-Math-Eval\\"\\nREVISION = \\"f64c82f5ce9249155ad7c70991a9711d92963cce\\"\\nCOLUMNS = [\\"model\\", \\"token_budget\\", \\"problem_id\\", \\"variant\\", \\"predicted_answer\\",\\n           \\"correct_strict\\", \\"answer_forced\\", \\"trace\\"]\\nMODELS = {\\"qwen3-1.7b\\", \\"qwen3-4b\\", \\"qwen3-8b\\", \\"qwen3-14b\\"}\\n\\n\\ndef load_partition(config: str, files: list[str], cache: Path) -> tuple[pd.DataFrame, list[dict]]:\\n    selected = sorted(f for f in files if f.startswith(f\\"data/{config}/\\") and f.endswith(\\".parquet\\"))\\n    if len(selected) != 4:\\n        raise ValueError(f\\"expected four model shards for {config}, found {len(selected)}\\")\\n    anchor = \\"base\\" if config == \\"math_perturb\\" else ANCHOR\\n    frames, manifest = [], []\\n    for filename in selected:\\n        path = Path(hf_hub_download(DATASET, filename, repo_type=\\"dataset\\", revision=REVISION,\\n                                    cache_dir=cache, token=False))\\n        frame = pd.read_parquet(path, columns=COLUMNS)\\n        keep = frame[\\"token_budget\\"].isin(BUDGETS) & (\\n            frame[\\"variant\\"].eq(anchor) | frame[\\"token_budget\\"].eq(LABEL_BUDGET)\\n        )\\n        retained = frame.loc[keep].copy()\\n        retained.loc[~retained[\\"variant\\"].eq(anchor), [\\"trace\\", \\"predicted_answer\\"]] = \\"\\"\\n        frames.append(retained)\\n        manifest.append({\\"path\\": filename, \\"bytes\\": path.stat().st_size,\\n                         \\"sha256\\": hashlib.file_digest(path.open(\\"rb\\"), \\"sha256\\").hexdigest(),\\n                         \\"source_rows\\": len(frame), \\"retained_rows\\": len(retained)})\\n        print(f\\"Loaded {filename}: {len(retained)} retained rows\\", flush=True)\\n    result = pd.concat(frames, ignore_index=True)\\n    if set(result[\\"model\\"]) != MODELS:\\n        raise ValueError(f\\"unexpected models in {config}\\")\\n    if result.duplicated([\\"model\\", \\"token_budget\\", \\"problem_id\\", \\"variant\\"]).any():\\n        raise ValueError(f\\"duplicate observations in {config}\\")\\n    return result, manifest\\n\\n\\ndef main() -> None:\\n    parser = argparse.ArgumentParser(description=__doc__)\\n    parser.add_argument(\\"--out-dir\\", type=Path, required=True)\\n    parser.add_argument(\\"--cache-dir\\", type=Path, default=Path(\\"data/e37_hf_cache\\"))\\n    args = parser.parse_args()\\n    started = time.time()\\n    args.out_dir.mkdir(parents=True, exist_ok=True)\\n    files = HfApi(token=False).list_repo_files(DATASET, repo_type=\\"dataset\\", revision=REVISION)\\n    math, math_manifest = load_partition(\\"math_perturb\\", files, args.cache_dir)\\n    gsm, gsm_manifest = load_partition(\\"gsm_plus\\", files, args.cache_dir)\\n    result = evaluate(math, gsm, bootstrap=5_000)\\n    result[\\"provenance\\"] = {\\n        \\"dataset\\": DATASET, \\"revision\\": REVISION, \\"files\\": math_manifest + gsm_manifest,\\n        \\"python\\": platform.python_version(), \\"bootstrap_replicates\\": 5_000,\\n        \\"packages\\": {p: importlib.metadata.version(p) for p in\\n                     (\\"numpy\\", \\"pandas\\", \\"scikit-learn\\", \\"scipy\\", \\"pyarrow\\", \\"huggingface-hub\\")},\\n        \\"seconds\\": time.time() - started,\\n    }\\n    payload = json.dumps(result, indent=2)\\n    (args.out_dir / \\"result.json\\").write_text(payload + \\"\\\\n\\", encoding=\\"utf-8\\")\\n    print(payload, flush=True)\\n\\n\\nif __name__ == \\"__main__\\":\\n    main()\\n", "train/test_eval_e36_budget_path.py": "import math\\n\\nimport pandas as pd\\n\\nfrom eval_e36_budget_path import build_examples, normalize_answer, repeated_line_fraction\\n\\n\\ndef _row(problem_id, model, budget, variant, correct, answer, forced=False, trace=\\"work\\\\nanswer\\"):\\n    return {\\n        \\"problem_id\\": problem_id,\\n        \\"model\\": model,\\n        \\"token_budget\\": budget,\\n        \\"variant\\": variant,\\n        \\"correct_strict\\": correct,\\n        \\"predicted_answer\\": answer,\\n        \\"answer_forced\\": forced,\\n        \\"trace\\": trace,\\n    }\\n\\n\\ndef test_normalize_answer():\\n    assert normalize_answer(\\" [ $X, Y$ ] \\") == \\"xy\\"\\n\\n\\ndef test_repeated_line_fraction():\\n    # `math.isclose` rather than `pytest.approx`: the pinned venv has no pytest, and the repo\\n    # runs its tests with `unittest discover`.\\n    assert math.isclose(repeated_line_fraction(\\"a\\\\na\\\\nb\\"), 1 / 3, rel_tol=1e-9)\\n\\n\\ndef test_build_math_examples_keeps_only_eligible_original():\\n    rows = []\\n    for budget in (2048, 4096, 8192, 16384):\\n        rows.append(_row(\\"p#base\\", \\"m\\", budget, \\"base\\", budget == 16384, \\"[1]\\"))\\n        rows.append(_row(\\"p#simple\\", \\"m\\", budget, \\"simple\\", True, \\"[1]\\"))\\n        rows.append(_row(\\"p#hard\\", \\"m\\", budget, \\"hard\\", True, \\"[1]\\"))\\n    result = build_examples(pd.DataFrame(rows), \\"math_perturb\\")\\n    assert len(result) == 1\\n    assert bool(result.iloc[0][\\"is_robust\\"])\\n    assert result.iloc[0][\\"answer_modal_fraction\\"] == 1.0\\n", "train/test_eval_e37_gsm_confirmation.py": "import pandas as pd\\n\\nfrom eval_e37_gsm_confirmation import build_gsm_examples\\n\\n\\nVARIANTS = (\\n    \\"numerical substitution\\",\\n    \\"digit expansion\\",\\n    \\"integer-decimal-fraction conversion\\",\\n    \\"adding operation\\",\\n    \\"reversing operation\\",\\n    \\"problem understanding\\",\\n    \\"distraction insertion\\",\\n    \\"critical thinking\\",\\n)\\n\\n\\ndef test_build_gsm_examples_groups_consecutive_ids_and_drops_critical():\\n    rows = []\\n    for budget in (2048, 4096, 8192, 16384):\\n        for offset, variant in enumerate(VARIANTS):\\n            rows.append({\\n                \\"problem_id\\": str(8 + offset),\\n                \\"model\\": \\"m\\",\\n                \\"token_budget\\": budget,\\n                \\"variant\\": variant,\\n                \\"correct_strict\\": variant != \\"critical thinking\\",\\n                \\"predicted_answer\\": \\"[1]\\",\\n                \\"answer_forced\\": False,\\n                \\"trace\\": \\"short solution\\",\\n            })\\n    result = build_gsm_examples(pd.DataFrame(rows))\\n    assert len(result) == 1\\n    assert result.iloc[0][\\"problem_id\\"] == \\"1\\"\\n    assert bool(result.iloc[0][\\"is_robust\\"])\\n", "protocols/E37_PROTOCOL.md": "# E37: independent confirmation of the frozen budget-path score\\n\\nStatus: pre-registered before reading any GSM-Plus correctness field or computing any E37\\nfeature/label association.\\n\\n## Motivation\\n\\nE36\'s unchanged reasoning-path classifier transferred from MATH-Perturb to Putnam-AXIOM with\\nROC-AUC 0.765 and a problem-bootstrap interval wholly above chance, including AUC 0.680--0.814\\nwithin each of four Qwen3 sizes.  It nevertheless missed its absolute-threshold balanced-\\naccuracy gate by 0.0025.  The ranking signal is therefore promising but E36 remains a formal\\nfailure and does not authorize an AIMO run.\\n\\nE37 is the one allowed confirmation.  It keeps E36\'s training data, 18 features, preprocessing,\\nlogistic model and score direction unchanged, replaces the distribution-sensitive absolute\\nthreshold with a prespecified within-model median rank, and evaluates on a third perturbation\\nbenchmark whose correctness outcomes have not been inspected.\\n\\n## Frozen data and label\\n\\nUse the `gsm_plus` config from `ssubhnil/Qwen3-Math-Eval` at revision\\n`f64c82f5ce9249155ad7c70991a9711d92963cce`.\\n\\nSchema-only inspection established that each source problem has eight consecutive IDs and one\\nrow for each documented GSM-Plus type.  Canonicalise `problem_id` as `int(problem_id) // 8`.\\nExclude `critical thinking`, whose gold target is an unanswerable sentinel according to the\\ndataset card.  Use the `problem understanding` rewrite as the anchor because it is the closest\\nanswer-preserving paraphrase among the seven scorable types.\\n\\nFor each `(canonical problem, model)` at 16,384 tokens:\\n\\n- eligible: the anchor is strictly correct;\\n- robust: all seven scorable variants are strictly correct;\\n- spurious: the anchor is correct and at most five of seven scorable variants are correct;\\n- ambiguous: exactly six of seven are correct; exclude it.\\n\\nPredictor inputs are the anchor trace at 2,048, 4,096, 8,192 and 16,384 tokens.  They are passed\\nthrough E36\'s committed `trace_features` unchanged.  Variant traces, correctness, ground truth,\\nquestion text and model identity are never predictor inputs.\\n\\n## Frozen predictor and decision\\n\\nRebuild the E36 model on all eligible model-specific MATH-Perturb examples exactly as committed\\nin `train/eval_e36_budget_path.py`.  Do not refit on Putnam or GSM-Plus.\\n\\nWithin each model\'s GSM-Plus batch, call the higher-scoring half robust using stable canonical-ID\\ntie-breaking.  This rank policy was selected before GSM-Plus labels were read.  It matches the\\nnear-balanced Codabench validation prior established by constant probes and avoids carrying a\\nMATH-calibrated probability threshold across sources.\\n\\n## Gates\\n\\nE37 passes only if every condition holds:\\n\\n1. GSM-Plus yields at least 50 robust and 50 spurious clear-cut configurations;\\n2. overall configuration-level ROC-AUC is at least 0.65;\\n3. a 5,000-replicate canonical-problem bootstrap has an AUC 95% lower bound above 0.50;\\n4. the frozen within-model half-rank decision has balanced accuracy at least 0.60;\\n5. every non-degenerate model AUC is at least 0.50 and at least three of four are at least 0.58.\\n\\nFailure closes the budget-path lane with no AIMO GPU run and no submission.  Passing authorizes\\none unchanged AIMO transfer experiment:\\n\\n- generate deterministic original traces at the same four budgets for all 34 labelled\\n  small-track `train-main-v2` configurations;\\n- use the frozen E36 model score and within-`(model_id, reasoning_effort)` higher-half decision;\\n- require problem-level AUC >= 0.70, template-bootstrap lower bound > 0.50, half-rank balanced\\n  accuracy above E27\'s constants, and an end-to-end measured runtime below 3,000 seconds.\\n\\nOnly if that transfer also passes may one frozen Codabench Small Models submission be uploaded.\\nNo feature, budget, label band, model coefficient, direction, threshold or rank fraction may be\\nchanged after GSM-Plus or AIMO outcomes are seen.\\n"}')
for name, text in entries.items():
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
subprocess.run([sys.executable, "-m", "pytest", "-q", "train/test_eval_e36_budget_path.py", "train/test_eval_e37_gsm_confirmation.py"], cwd=root, check=True)
